def biggest(numbers):
    best = numbers[0]
    for n in numbers:
        if n > best:
            best = n
    return best

assert biggest([3, 9, 4]) == 9
assert biggest([-5, -2]) == -2
assert biggest([7]) == 7
print("typical, negative and single cases pass")

